<?php
 namespace App\Library; use App\Order; use App\User; use App\FundRecord; use Illuminate\Support\Facades\DB; use Illuminate\Support\Facades\Log; class FundHelper { const ACTION_CONTINUE = 1001; public static function orderSuccess($order_id, callable $processOrder) { $order = null; try { return DB::transaction(function () use ($order_id, &$order, $processOrder) { $order = \App\Order::where('id', $order_id)->lockForUpdate()->firstOrFail(); $ret = $processOrder($order); if ($ret !== self::ACTION_CONTINUE) { return $ret; } $user = User::where('id', $order->user_id)->lockForUpdate()->firstOrFail(); $user->m_all += $order->income; $user->saveOrFail(); $fund_record = new FundRecord; $fund_record->user_id = $order->user_id; $fund_record->type = FundRecord::TYPE_IN; $fund_record->amount = $order->income; $fund_record->all = $user->m_all; $fund_record->frozen = $user->m_frozen; $fund_record->paid = $user->m_paid; $fund_record->balance = $user->m_balance; $fund_record->remark = '订单#' . $order->order_no; $fund_record->order_id = $order->id; $fund_record->saveOrFail(); return true; }); } catch (\Throwable $e) { $msg = 'FundHelper.orderSuccess error, order_id:' . $order_id; if ($order) $msg .= ', user_id:' . $order->user_id . ',income:' . $order->income . ',order_no:' . $order->order_no; Log::error($msg . ' with exception:', ['Exception' => $e]); return false; } } public static function orderFreeze($order_id, $frozen_reason) { $order = null; try { return DB::transaction(function () use ($order_id, &$order, $frozen_reason) { $order = \App\Order::where('id', $order_id)->lockForUpdate()->firstOrFail(); if ($order->status === Order::STATUS_REFUND) { return false; } if ($order->status === Order::STATUS_FROZEN) { return true; } $origin_status = $order->status; if ($origin_status === \App\Order::STATUS_SUCCESS) { $statusTxt = '已发货'; } elseif ($origin_status === \App\Order::STATUS_UNPAY) { $statusTxt = '未付款'; } elseif ($origin_status === \App\Order::STATUS_PAID) { $statusTxt = '未发货'; } else { throw new \Exception('unknown'); } $user = User::where('id', $order->user_id)->lockForUpdate()->firstOrFail(); $fund_record = new FundRecord; $fund_record->user_id = $order->user_id; $fund_record->type = FundRecord::TYPE_OUT; $fund_record->order_id = $order->id; $fund_record->remark = $order === $order ? '' : '关联订单#' . $order->order_no . ': '; if ($origin_status === \App\Order::STATUS_SUCCESS) { $user->m_frozen += $order->income; $user->saveOrFail(); $fund_record->amount = -$order->income; $fund_record->remark .= $frozen_reason . ', 冻结订单#' . $order->order_no; } else { $fund_record->amount = 0; $fund_record->remark .= $frozen_reason . ', 冻结订单(' . $statusTxt . ')#' . $order->order_no; } $fund_record->all = $user->m_all; $fund_record->frozen = $user->m_frozen; $fund_record->paid = $user->m_paid; $fund_record->balance = $user->m_balance; $fund_record->saveOrFail(); $order->status = \App\Order::STATUS_FROZEN; $order->frozen_reason = ($order === $order ? '' : '关联订单#' . $order->order_no . ': ') . $frozen_reason; $order->saveOrFail(); return true; }); } catch (\Throwable $e) { $msg = 'FundHelper.orderFreeze error'; if ($order) $msg .= ', order_no:' . $order->order_no . ', user_id:' . $order->user_id . ', amount:' . $order->income; else $msg .= ', order_no: null'; Log::error($msg . ' with exception:', ['Exception' => $e]); return false; } } public static function orderUnfreeze($order_id, $reason, callable $doInTransaction = null, &$outerStatus = null) { $order = null; try { return DB::transaction(function () use ($order_id, &$order, $reason, $doInTransaction, &$outerStatus) { $order = \App\Order::where('id', $order_id)->lockForUpdate()->firstOrFail(); if ($doInTransaction !== null) { $ret = $doInTransaction(); if ($ret !== self::ACTION_CONTINUE) { return $ret; } } if ($order->status === Order::STATUS_REFUND) { $outerStatus = $order->status; return false; } if ($order->status !== Order::STATUS_FROZEN) { $outerStatus = $order->status; return true; } $is_already_income = $order->card_orders()->exists(); if ($is_already_income) { $outerStatus = \App\Order::STATUS_SUCCESS; $statusTxt = '已发货'; } else { if ($order->paid_at === NULL) { $outerStatus = \App\Order::STATUS_UNPAY; $statusTxt = '未付款'; } else { $outerStatus = \App\Order::STATUS_PAID; $statusTxt = '未发货'; } } $user = User::where('id', $order->user_id)->lockForUpdate()->firstOrFail(); $fund_record = new FundRecord; $fund_record->user_id = $order->user_id; $fund_record->type = FundRecord::TYPE_IN; $fund_record->remark = $order === $order ? '' : '关联订单#' . $order->order_no . ': '; $fund_record->order_id = $order->id; if ($is_already_income) { $user->m_frozen -= $order->income; $user->saveOrFail(); $fund_record->amount = $order->income; $fund_record->remark .= $reason . ', 解冻订单#' . $order->order_no; } else { $fund_record->amount = 0; $fund_record->remark .= $reason . ', 解冻订单(' . $statusTxt . ')#' . $order->order_no; } $fund_record->all = $user->m_all; $fund_record->frozen = $user->m_frozen; $fund_record->paid = $user->m_paid; $fund_record->balance = $user->m_balance; $fund_record->saveOrFail(); $order->status = $outerStatus; $order->saveOrFail(); return true; }); } catch (\Throwable $e) { $msg = 'FundHelper.orderUnfreeze error'; if ($order) $msg .= ', order_no:' . $order->order_no . ', user_id:' . $order->user_id . ',amount:' . $order->income; else $msg .= ', order_no: null'; Log::error($msg . ' with exception:', ['Exception' => $e]); return false; } } }